\label{assumption:regularizaion}
The function $\varphi$ belongs to $\mathcal{C}^2((0,\infty))$, satisfies
$\varphi''(s)>0$ for $s>0$, and there exist
$\beta\ge0$ and $\lambda_0,\lambda_1,\lambda_2\ge0$
such that
\begin{equation}\label{eq:Aphi}
\frac{1}{\varphi''(s)}
\le\lambda_0s^{-\beta}+\lambda_1+\lambda_2s,
\qquad s>0.
\end{equation}

\cite[Corollary 3.2]{alberto.gonzalez-marcel.nutz_austin.stromme2026}\label{proposition:ROT_bias_parametric_bound}
Under \Cref{assumption:regularizaion} and compact support assumption, 
\begin{equation}
\Bigl|
\mathbb{E}\mathsf {OT}_{\varepsilon}^c(\mu_n,\nu_n)-\mathsf {OT}_{\varepsilon}^c(\mu,\nu)
\Bigr|
\leq
2\sqrt{2}\,
(5\|c\|_\infty + \varepsilon)
\frac{
\psi'(\frac{6\|c\|_\infty + \varepsilon}{\varepsilon})
}{\sqrt{n}}.
\label{eq:imported-bias}
\end{equation}

\label{lemma:GW-linearization}
Suppose $\mu\in\mathcal{P}_{rs}(\mathcal{X})$ and $\nu\in\mathcal{P}_{rs}(\mathcal{Y})$.
If $\pi^*$ is a finite minimizer of
\[
\pi\longmapsto
\mathcal{E}_\Gamma(\pi)+\varepsilon \,\mathsf{D}_\varphi(\pi,\mu\otimes\nu)
\quad\text{over }\Pi(\mu,\nu),
\]
then we have for 
$c_*(x,y):=2\int\Gamma((x,y),(x',y'))\,d\pi^*(x',y')$,
\begin{equation}
\label{eq:GW-linearized-OT}
\pi^*\in
\operatorname*{argmin}_{\theta\in\Pi(\mu,\nu)}
\left\{
\int c_*\,d\theta
+
\varepsilon \,\mathsf{D}_\varphi(\theta,\mu\otimes\nu)
\right\}.
\end{equation}

\label{lemma:conjugate-regularity}
Suppose \Cref{assumption:regularizaion} holds.
Then $\psi$ is finite and belongs to $\mathcal{C}^1(\mathbb{R})$, with
$\psi'\ge0$, $\psi'(1)=1$, and $\psi'(s)\to\infty$ as $s\to\infty$.
Moreover, $\psi$ is strictly convex on $[1-\delta,\infty)$
for some $\delta>0$.
For every compact interval $I$, there exists $L_I<\infty$ such that
\begin{equation}
\label{eq:holder-psi}
|\psi'(s)-\psi'(t)|\le L_I|s-t|^\frac{1}{1+\beta},
\qquad s,t\in I.
\end{equation}
For every $\theta\in(0,1)$, there also exists
$\kappa_{I,\theta}>0$ such that
\begin{equation}
\label{eq:active-curvature}
B_\psi(s,t):=\psi(s)-\psi(t)-\psi'(t)(s-t)
\ge\kappa_{I,\theta}|s-t|^2
\quad\text{if }s,t\in I,\ \psi'(t)\ge\theta.
\end{equation}

\label{proposition:Agamma}
Suppose that both $(\mu,\nu)$ and $(\tilde\mu,\tilde\nu)$ satisfy \Cref{assumption:Agamma} for the same $r,s\in[1,\infty)$ and $p\in[1,\infty]$. Then there exists $\Lambda>0$ such that
\begin{equation}\label{eq:Agamma}
\left|\mathcal{E}_{\Gamma_{r,s}}(\pi)-\mathcal{E}_{\Gamma_{r,s}}(\widetilde\pi)\right|
\le\Lambda W_p(\pi,\widetilde\pi)
\end{equation}
for all $\pi\in\Pi(\mu,\nu)$ and
$\widetilde\pi\in\Pi(\tilde\mu,\tilde\nu)$.

\label{thm:continuity_regualarized_GW_value}
Suppose $(\mu,\nu)$ and $(\tilde\mu,\tilde\nu)$ both satisfy \Cref{assumption:Agamma}. Then
\begin{align*}
|S_{r,s,\varepsilon}(\mu,\nu) 
- 
S_{r,s,\varepsilon}(\tilde\mu,\tilde\nu)| 
\leq
\Lambda W_p( (\mu,\nu),(\tilde\mu,\tilde\nu) )
\end{align*}

\label{lemma:strong-convexity-tv}
Suppose \Cref{assumption:regularizaion} and  \Cref{assumption:Cgamma} hold. If
$\pi\in\Pi(\mu,\nu)$ and $\pi^*$ is the optimizer of $S_{r,s,\varepsilon}$
and $h:\mathcal{X}\times\mathcal{Y}\to[0,\infty)$ is measurable with
$\int_{\mathcal{X}\times\mathcal{Y}}h^2\,d(\mu\otimes\nu+\pi^*+\pi)<\infty$,
then
\begin{align}\label{eq:objective-tv}
\|h(\pi&-\pi^*)\|_{\mathrm{TV}}^{\beta+2}\nonumber\\
&\le
\frac{ (\beta+1)(\beta+2)3^{\beta/2}((\lambda_0+\lambda_1)\vee\lambda_2)}{\varepsilon-\kappa}
\|h\|_{L^2(\mu\otimes\nu+\pi^*+\pi)}^{\beta+2}
\bigl(\mathcal{F}_\varepsilon^{\mu,\nu}(\pi)
-
\mathcal{F}_\varepsilon^{\mu,\nu}(\pi^*)\bigr).
\end{align}

Let $\pi\in\Pi(\mu,\nu)$ be the $p$-shadow of $\widetilde\pi^*$. \Cref{proposition_shadow_property} and \Cref{proposition:Agamma} indicate that 
\begin{align*}
\mathcal{F}_\varepsilon^{\mu,\nu} (\pi) -  \mathcal{F}_\varepsilon^{{\tilde\mu,\tilde\nu}} (\widetilde\pi^*)
=
\mathcal{E}_\Gamma(\pi) - \mathcal{E}_\Gamma(\widetilde\pi^*) + \varepsilon ( \mathsf{D}_\varphi (\pi, \mu\otimes\nu) - \mathsf{D}_\varphi (\widetilde\pi^*, \tilde\mu\otimes\tilde\nu) ) \\
\leq
\mathcal{E}_\Gamma(\pi) - \mathcal{E}_\Gamma(\widetilde\pi^*)
\leq
\Lambda W_p(\pi, \widetilde\pi^*) = \Lambda \Delta.
\end{align*}
Since $\pi^*$ minimizes $\mathcal{F}_\varepsilon^{\mu,\nu}(\cdot)$ over $\Pi(\mu,\nu)$,
\begin{align}\label{eq:first-shadow-objective}
    \mathcal{F}_\varepsilon^{\mu,\nu}(\pi^*) 
    \leq 
    \mathcal{F}_\varepsilon^{\mu,\nu}(\pi) 
    \leq
    \mathcal{F}_\varepsilon^{{\tilde\mu,\tilde\nu}}(\widetilde\pi^*) + \Lambda \Delta.
\end{align}
Similarly,
 \begin{align}\label{eq:reverse-shadow-objective}
     \mathcal{F}_\varepsilon^{{\tilde\mu,\tilde\nu}}(\widetilde\pi^*) 
     \leq
     \mathcal{F}_\varepsilon^{\mu,\nu}(\pi^*)
     +
     \Lambda \Delta.
 \end{align}
Combining \eqref{eq:first-shadow-objective} and
\eqref{eq:reverse-shadow-objective} yields the value-gap estimate 
\begin{equation}\label{eq:shadow-objective-gap}
0\leq
\mathcal{F}_\varepsilon^{\mu,\nu}(\pi)-\mathcal{F}_\varepsilon^{\mu,\nu}(\pi^*)
=
\bigl(
\mathcal{F}_\varepsilon^{\mu,\nu}(\pi) - \mathcal{F}_\varepsilon^{\tilde\mu,\tilde\nu}(\tilde\pi^*)
\bigr)
+
\bigl(
\mathcal{F}_\varepsilon^{\tilde\mu,\tilde\nu}(\tilde\pi^*)
-
\mathcal{F}_\varepsilon^{\mu,\nu}(\pi^*)
\bigr)
\le2\Lambda\Delta.
\end{equation}
Since  $\mu\in\mathcal{P}_{2q}(\mathcal{X})$ and $\nu\in\mathcal{P}_{2q}(\mathcal{Y})$, Cauchy-Schwarz inequality gives that                                            
\begin{align*}
B_{\mu,\nu,q}
&:=
\sup_{\eta_1,\eta_2\in\Pi(\mu,\nu)}
\int_{\mathcal{X}\times\mathcal{Y}}(d_{\mathcal{X}}(x,x_{0})^q + d_{\mathcal{Y}}(y,y_{0})^q)^2\,d(\mu\otimes\nu+\eta_1+\eta_2)(x,y)\\
&\le
6
\int_{\mathcal{X}}d_{\mathcal{X}}(x,x_{0})^{2q}\,d\mu(x)
+
6
\int_{\mathcal{Y}}d_{\mathcal{Y}}(y,y_{0})^{2q}\,d\nu(y)
<\infty,
\end{align*}
for any fixed $(x_{0},y_{0})\in\mathcal{X}\times\mathcal{Y}$. Apply \eqref{eq:objective-tv} with $h=w_q:=
d_{\mathcal{X}}(x,x_{0})^q + d_{\mathcal{Y}}(y,y_{0})^q$. Since
$\pi^*,\pi\in\Pi(\mu,\nu)$, \eqref{eq:shadow-objective-gap} gives
\begin{equation}\label{eq:weighted-tv-shadow}
\|w_q(\pi^*-\pi)\|_{\mathrm{TV}}^{\beta+2}
\le
\frac{2(\beta+1)(\beta+2)3^{\beta/2}((\lambda_0+\lambda_1)\vee\lambda_2)
B_{\mu,\nu,q}^{(\beta+2)/2}\Lambda\Delta}
{\varepsilon-\kappa}.
\end{equation}
The weighted variation estimate
\cite[Proposition~7.10]{villani2021topics} states that
\begin{equation}\label{eq:Wq-tv}
W_q(\pi^*,\pi)^q
\le
2^{q-1}\|w_q(\pi^*-\pi)\|_{\mathrm{TV}}.
\end{equation}
Combining \eqref{eq:weighted-tv-shadow} and \eqref{eq:Wq-tv}, we obtain 
\begin{equation}\label{eq:Wq-first}
W_q(\pi^*,\pi)
\le
2^{1-1/q}B_{\mu,\nu,q}^{1/(2q)}
\left(
\frac{2(\beta+1)(\beta+2)3^{\beta/2}((\lambda_0+\lambda_1)\vee\lambda_2)\Lambda\Delta}
{\varepsilon-\kappa}
\right)^{1/[q(\beta+2)]}.
\end{equation}
For every $\gamma\in\Pi(\pi,\widetilde\pi^*)$, using H\"{o}lder inequality twice gives
\begin{align*}
\left(\int d_{\mathcal{X}\times\mathcal{Y},q}(z,\tilde z )^q\,d\gamma(z,\tilde z)\right)^{1/q}
&\le
2^{1/q-1/p}
\left(\int d_{\mathcal{X}\times\mathcal{Y},p}(z,\tilde z)^q\,d\gamma(z,\tilde z)\right)^{1/q}\\
&\le
2^{1/q-1/p}
\left(\int d_{\mathcal{X}\times\mathcal{Y},p}(z,\tilde z)^p\,d\gamma(z,\tilde z)\right)^{1/p}
\end{align*}
when $p<\infty$, with the essential-supremum interpretation when
$p=\infty$. Taking infima over $\gamma$ and using
\Cref{proposition_shadow_property} yields
\begin{equation}\label{eq:Wq-second}
W_q(\pi,\widetilde\pi^*)
\le
2^{1/q-1/p}W_p(\pi,\widetilde\pi^*)
=2^{1/q-1/p}\Delta.
\end{equation}
The triangle inequality, together with \eqref{eq:Wq-first} and
\eqref{eq:Wq-second}, proves \eqref{eq:main-bound}.

\label{thm:gw-duality}
Let $\mu\in\mathcal{P}(\mathbb{R}^{d_x})$ and $\nu\in \mathcal{P}(\mathbb{R}^{d_y})$ be compactly supported. For every $M\ge M_{\mu,\nu}$,
\begin{align}\label{eq:gw-variational-duality}
&\quad S_{2,2,\varepsilon}(\mu,\nu) -\mathsf{GW}^1(\mu,\nu)\\
=&
\min_{A\in\mathbb{R}^{d_x\times d_y}}
\left\{32\|A\|_F^2+\mathsf {OT}_{\varepsilon}^{c_A}(\mu,\nu)\right\}
=
\min_{A\in\mathcal D_M}
\left\{32\|A\|_F^2+\mathsf {OT}_{\varepsilon}^{c_A}(\mu,\nu)\right\}.\nonumber
\end{align} Equivalently,
\begin{equation}
\begin{split}
S_{2,2,\varepsilon}(\mu,\nu)-\mathsf{GW}^1(\mu,\nu)
=
&\min_{A\in\mathcal D_M}
\max_{\substack{f\in \mathcal{C}(\mathcal{X})\\g\in \mathcal{C}(\mathcal{Y})}}
\biggl\{
32\|A\|_F^2+\int f\, d\mu+\int g\,d\nu \\
&-\varepsilon\int
\psi\!\left(
\frac{f(x)+g(y)-c_A(x,y)}{\varepsilon}
\right)\,d(\mu\otimes\nu)(x,y)
\biggr\}.
\end{split}
\label{eq:gw-potential-duality}
\end{equation}
For each \(A\in\mathbb{R}^{d_x\times d_y}\), the inner ROT problem admits a unique optimizer \(\pi_A\).
The GW minimizers and the outer minimizers in either matrix domain,
correspond bijectively through
\begin{equation}
\pi^*=\pi_{A^*},
\qquad
A^*=\frac12\int xy^\top\,d\pi^*(x,y).
\label{eq:optimal-matrix-moment}
\end{equation}

\label{lem:gw-cost-bounds}
Under the assumption of 
Theorem~\ref{thm:gw-duality}. We have
\begin{align}
\sup_{A\in D}\|c_A\|_\infty\le 20R_x^2R_y^2,
\quad
\|c_A-c_{A'}\|_\infty\le32R_xR_y\|A-A'\|_F, \,\, A,A'\in \mathcal D.\nonumber\\
 |c_A(x,y)-c_A(x',y)|\le24R_xR_y^2\|x-x'\|,
 \quad
 |c_A(x,y)-c_A(x,y')|\le24R_x^2R_y\|y-y'\|.
 \label{eq:gw-spatial-cost-bounds}
\end{align}

\label{lem:covering}
Then there exist an integer $J$ satisfying
\begin{equation}
 1\le J
 \le
 \left(
 1+\frac{192R_x^2R_y^2(4L)^{(1+\beta)}}{\varepsilon}
 \right)^{d_x}
 \label{eq:covering-J-bound}
\end{equation}
and a constant $C\ge1$ depending on $R_x,d_x,R_y,d_y,\varphi,\varepsilon$ such that 
\begin{equation}
 \log N(\eta,\mathcal{H},\|\cdot\|_\infty)
 \le
2(1+\beta)(d_xd_y+J)
\log(1+ C/\eta),
 \qquad \eta>0.
 \label{eq:entropy-bound}
\end{equation}

\label{lem:empirical-reduction}
Under the assumption of  Theorem~\ref{thm:gw-duality}, 
we have, 
\begin{equation}
\begin{aligned}
|S_{2,2,\varepsilon}(\mu_n,\nu_n)-S_{2,2,\varepsilon}(\mu,\nu)|
\le
|\mathsf{GW}^1(\mu_n,\nu_n)-&\mathsf{GW}^1(\mu,\nu)|
+
|V_\varepsilon(\mu_n,\nu_n)-V_\varepsilon(\mu,\nu)|\\
&\quad+
8R_xR_y^2\|\mu_nx\|
+
8R_x^2R_y\|\nu_ny\|.
\end{aligned}
\label{eq:empirical-gw-reduction}
\end{equation}

\label{thm:parametric_sample_complexity}
Suppose Assumption~\ref{assumption:regularizaion} holds
and $\mu,\nu$ have compact supports. Then there exists a finite constant
$C\geq0$ depending on 
$\varphi,R_x,d_x,R_y,d_y,\varepsilon$, such that
\begin{align}
 \mathbb{E}\bigl|S_{2,2,\varepsilon}(\mu_n,\nu_n)-S_{2,2,\varepsilon}(\mu,\nu)\bigr|^2
\le Cn^{-1}.\label{eq:main-l2}
\end{align}
